update public.lessons l set enhancements = $ench${"industryStory":"Consider a team whose dashboard proudly showed 100% green for months. A billing bug still reached production: invoices rendered, so every check passed, but the totals were wrong by a rounding error nobody had encoded an assertion for. The tests confirmed exactly what they were told to confirm and nothing more. The team had mistaken coverage of screens for coverage of risk.","badGood":{"label":"How you describe a passing suite","bad":"All the tests are green, so the release is good to go.","good":"The suite is green, which covers login, checkout, and search regression. Payment retries and the new export flow are not automated yet — I have exploratory notes on those before we ship."},"davidTip":"Get into the habit of naming a check after the risk it retires, not the page it visits. \"places order with correct VAT\" ages far better than \"checkout test\", and it forces you to know why the check exists before you write a line of it.","visualAid":{"type":"comparison","title":"Checking versus testing","headers":["Aspect","Checking (automatable)","Testing (human)"],"rows":[["Goal","Confirm a known fact holds","Learn something new about the product"],["Nature","Algorithmic, repeatable","Exploratory, judgement-led"],["Finds","Regressions in known behaviour","Risks and bugs nobody imagined"],["Green means","This encoded behaviour still holds","Not applicable — testing is an activity, not a result"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 1 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"Teams often discover their flakiest, most-hated tests are the ones written against features that were still being designed. The behaviour changed weekly, the checks broke weekly, and eventually people started ignoring the failures — which quietly disabled the safety net for everything else too. The fix was rarely a better tool; it was waiting for the interface to settle before investing.","davidTip":"When you feel the urge to automate something immediately, ask \"will this behaviour still look the same in three sprints?\" If the honest answer is no, note it as a candidate and move on. Restraint is a senior automation skill.","miniChallenge":"Find one existing check in a codebase you have access to that scores low on all four lenses. Write two sentences arguing for deleting it, and what you would trust instead.","visualAid":{"type":"flow","title":"Deciding on an automation candidate","steps":[{"label":"State the risk","detail":"What breaks, and who cares if it does silently?"},{"label":"Score the four lenses","detail":"Stability, value, frequency, risk — 1 to 3 each."},{"label":"Choose the level","detail":"Could this be checked lower down (unit/API) more cheaply?"},{"label":"Automate, defer, or leave manual","detail":"Commit to a decision you can justify aloud."}]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 1 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"badGood":{"label":"Reacting to an intermittent failure","bad":"It's flaky, just hit re-run — it'll go green on the second try.","good":"It's failing intermittently, so I've quarantined it out of the blocking path and raised a ticket. Either we make it wait on a real signal or we delete it — we can't have a check the team learns to ignore."},"davidTip":"Never write a hard-coded sleep to \"fix\" a timing failure. It hides a race rather than resolving it, and it taxes every future run. Wait on the actual condition you care about — the element being visible, the request completing — and the flakiness usually disappears with it.","industryStory":"A common pattern: a suite grows for a year, nobody ever removes anything, and builds creep from four minutes to nineteen. Developers start pushing without waiting for results because the feedback arrives too late to be useful. The suite was still green — it had simply become too slow and too noisy to change anyone's behaviour, which is the same as providing no evidence at all.","visualAid":{"type":"comparison","title":"Authoring cost versus total cost of ownership","headers":["Cost","Paid once (authoring)","Paid for the life of the check"],"rows":[["Writing the check","Yes","No"],["Fixing it when the product changes","No","Yes, repeatedly"],["Runtime added to every build","No","Yes, every run"],["Triage of each failure","No","Yes, per failure"],["Trust erosion from flakiness","No","Yes, compounding"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 1 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A recognisable trajectory: a team automates entirely through the browser because it feels like the most realistic testing. For a while it works. Then the suite hits an hour, flakes daily, and a single failing journey takes an afternoon to diagnose. The rescue is rarely a faster browser tool — it is moving the bulk of the logic checks down to unit and API level and keeping only a handful of end-to-end journeys for the things that genuinely need the whole stack.","davidTip":"When a UI check keeps breaking, ask \"what is this actually verifying?\" Nine times out of ten it is business logic that would sit far more happily one or two layers down. Move it, and keep the browser for what only the browser can prove.","visualAid":{"type":"comparison","title":"Choosing a layer","headers":["Layer","Speed","Stability","Best for"],"rows":[["Unit","Milliseconds","High","Logic: rules, validation, state transitions"],["Integration","Fast","Medium-high","Wiring between units, real DB or module boundaries"],["API / service","Moderate","High (contracts change slowly)","Business rules and error handling without a browser"],["UI / end-to-end","Slow","Low","A thin layer proving the whole flow works for a user"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 1 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"davidTip":"Treat your commit messages as notes to the next engineer, who might be you in six months. \"test: pin discount-before-VAT ordering\" tells a story; \"add tests\" tells nothing. The habit costs seconds and pays back every time someone has to understand why a check exists.","badGood":{"label":"Starting work on automating a new feature","bad":"Open the app, click through the feature, and start writing browser checks that reproduce what you clicked.","good":"Read how the feature is implemented, note where it can fail, decide which risks belong at which layer, then add checks in small committed steps — each naming the risk it retires."},"miniChallenge":"Take a check you have written before and rewrite its history as three small commits instead of one, each with a message that names the risk it addresses. Notice how much clearer the intent becomes.","visualAid":{"type":"flow","title":"The engineer's loop for a new check","steps":[{"label":"Read","detail":"Understand how the behaviour works and where it can fail."},{"label":"Frame","detail":"Name the risk and choose the cheapest honest layer."},{"label":"Step","detail":"Write and run a small increment; confirm it does what you expect."},{"label":"Commit","detail":"Record the change with a message that states the risk it retires."},{"label":"Review","detail":"Raise it like product code — small, legible, revertible."}]}}$ench$::jsonb
