update public.lessons l set enhancements = $ench${"industryStory":"A team adopted Playwright, saw the example test go green in CI, and told stakeholders automation was \"in place\". Weeks later a release broke checkout, yet the pipeline stayed green — the only test running was still the scaffolded example against an unrelated demo site. The lesson stuck: a passing suite is only meaningful when the tests exercise your own application.","davidTip":"Before you write any tests, spend ten minutes reading `playwright.config.ts` and deleting what you do not need. Starting from a config you understand beats inheriting one you copied.","miniChallenge":"Add an npm script `\"test:e2e\": \"playwright test\"` to `package.json` and run your suite through `npm run test:e2e` instead of `npx`. This is the entry point CI will call."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 4 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"test independence","bad":"~~~ts\ntest('logs in', async ({ page }) => {\n  await page.goto('/login');\n  await page.getByLabel('Email').fill('user@example.com');\n  await page.getByLabel('Password').fill('secret');\n  await page.getByRole('button', { name: 'Sign in' }).click();\n});\n\ntest('sees the dashboard', async ({ page }) => {\n  // assumes the previous test already logged in — it did not, contexts are isolated\n  await expect(page.getByRole('heading', { name: 'Dashboard' })).toBeVisible();\n});\n~~~","good":"~~~ts\ntest.beforeEach(async ({ page }) => {\n  await page.goto('/login');\n  await page.getByLabel('Email').fill('user@example.com');\n  await page.getByLabel('Password').fill('secret');\n  await page.getByRole('button', { name: 'Sign in' }).click();\n});\n\ntest('sees the dashboard after login', async ({ page }) => {\n  await expect(page.getByRole('heading', { name: 'Dashboard' })).toBeVisible();\n});\n~~~"},"davidTip":"If two tests must share expensive setup like authentication, do it through a storage-state fixture, not by chaining tests. Sharing state through a fixture keeps isolation; sharing it through execution order destroys it.","miniChallenge":"Take a test that currently depends on a previous test's state and make it self-sufficient by moving the setup into a `beforeEach`. Confirm it passes when run alone."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 4 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A suite leaned heavily on CSS selectors generated from a component library's class names. A routine dependency upgrade reshuffled those class names and hundreds of tests failed overnight — none because of a real defect. Rewriting the worst offenders as `getByRole` and `getByLabel` locators made the suite survive the next three upgrades untouched.","badGood":{"label":"brittle vs resilient locator","bad":"~~~ts\nawait page.locator('div.card > div:nth-child(2) > button.btn-primary').click();\n~~~","good":"~~~ts\nawait page.getByRole('button', { name: 'Add to basket' }).click();\n~~~"},"visualAid":{"type":"comparison","title":"Locator strategy at a glance","headers":["Strategy","Coupled to","Survives a restyle?"],"rows":[["getByRole / getByLabel","Behaviour and accessible name","Yes"],["getByText","Visible content","Usually"],["getByTestId","An explicit test hook","Yes, if the hook is kept"],["CSS / XPath","DOM structure and classes","Rarely"]]},"miniChallenge":"Find one `.first()` in your suite and replace it with a scoped or filtered locator that is unambiguous on its own. Confirm the test still passes."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 4 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"davidTip":"When an action mysteriously fails, do not add a sleep — run with `--debug` and read which actionability check never passed. \"Element is not visible\" and \"element is covered by another element\" point straight at the real problem, usually a modal or a sticky header you forgot about.","badGood":{"label":"entering text","bad":"~~~ts\nawait page.getByLabel('Email').click();\nawait page.waitForTimeout(500);\nawait page.getByLabel('Email').pressSequentially('user@example.com');\n~~~","good":"~~~ts\nawait page.getByLabel('Email').fill('user@example.com');\n~~~"},"miniChallenge":"Take a test that uses `pressSequentially` for a plain text field and switch it to `fill`. Time both runs and note the difference."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 4 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A suite of a few hundred tests was reliably green until someone noticed a bug had shipped that the tests should have caught. The cause was a family of assertions missing their `await` — copied and pasted across dozens of specs. They had never once failed, because a fire-and-forget assertion cannot fail. A lint rule for floating promises was added the same day and immediately lit up the offending lines.","davidTip":"Treat a test with no assertion, or only a \"toBeVisible\" on a container, as unfinished. The question to ask in review is always: \"if the feature silently broke, would this test go red?\" If the answer is no, the test is decoration.","visualAid":{"type":"flow","title":"How a web-first assertion resolves","steps":["Query the locator against the current DOM","Check the expectation (text, visibility, count...)","If met, pass immediately","If not met and time remains, wait a beat and re-query","If the timeout expires, fail with the last observed state"]},"miniChallenge":"Find a test that uses `waitForSelector` or `waitForTimeout` before checking something. Delete the wait and let a web-first assertion do the waiting instead. Confirm it still passes."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 4 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team burned two days blaming Playwright for a test that failed only in CI. When they finally enabled traces and opened one, the DOM snapshot showed a consent banner — present on the CI viewport but dismissed by a browser profile locally — sitting over the button the test clicked. The fix was one line of setup. The real lesson was that the trace should have been the first move, not the last.","davidTip":"Develop new tests in `--ui` mode from the start. Watching each step resolve, and seeing the page state at the moment an assertion runs, catches wrong locators and bad assumptions long before the test reaches CI.","badGood":{"label":"reacting to a timeout","bad":"~~~ts\n// \"It times out sometimes, so give it longer.\"\nawait expect(page.getByRole('alert')).toBeVisible({ timeout: 30000 });\n~~~","good":"~~~ts\n// Open the trace, find the cookie banner covering the button, dismiss it in setup,\n// then keep the default timeout because the real cause is fixed.\nawait page.getByRole('button', { name: 'Accept cookies' }).click();\nawait page.getByRole('button', { name: 'Save' }).click();\nawait expect(page.getByRole('alert')).toBeVisible();\n~~~"},"miniChallenge":"Enable `trace: 'on-first-retry'`, force a test to fail, and practise opening the resulting trace with `npx playwright show-trace`. Find the exact step where expected and actual diverged."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 4 and l.lesson_number = 6;

update public.lessons l set enhancements = $ench${"industryStory":"A suite passed on every developer's machine but failed unpredictably in CI. The cause was config drift: local runs quietly had retries enabled and a generous timeout, while CI did not. Nobody could reproduce anyone else's results. Consolidating everything into one environment-driven `playwright.config.ts`, reviewed like production code, ended the \"works for me\" standoffs within a sprint.","davidTip":"Make retries visible, not invisible. A test that only ever passes on its second attempt is a defect wearing a green badge — put a retry count in the report and treat any persistent retrier as a bug to investigate, not a setting to leave running.","visualAid":{"type":"comparison","title":"Config in one place vs scattered across tests","headers":["Concern","Scattered in tests","Centralised in config"],"rows":[["Base URL","Hardcoded per test","baseURL set once"],["Browsers","Whatever ran locally","projects run all of them"],["Retries","Ad hoc, inconsistent","CI-only, explicit"],["Portability","Works for me","Same run everywhere"]]},"miniChallenge":"Add a second project to your config for a mobile viewport using `devices['iPhone 13']` and run your existing suite across both desktop and mobile without changing any test."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 4 and l.lesson_number = 7;


