-- ============================================================
-- Lesson enhancements for "modern-test-automation-bootcamp" Module 7.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/modern-automation-module7.mjs and regenerate. Run AFTER
