update public.lessons l set enhancements = $ench${"industryStory":"A team started with a dozen clear Playwright specs and, anticipating growth, built an elaborate framework of base classes and abstract page objects before the suite reached fifty tests. Two years later most of those abstractions were still half-used, and new engineers spent their first week learning the framework rather than the product. A neighbouring team kept their suite flat and extracted structure only when a change hurt; their suite grew larger yet stayed easier to read. The lesson was not \"structure is bad\" — it was that structure earned in response to pain fits, and structure imagined up front rarely does.","visualAid":{"type":"comparison","title":"When does a flat suite need structure?","headers":["Signal","Flat suite is fine","Time to add a seam"],"rows":[["Suite size","A handful of specs","Dozens, many authors"],["A product change","Touches one spec","Touches many specs"],["Same flow appears","Once","Copy-pasted repeatedly"],["A newcomer","Can read it all","Cannot find or place a test"]]},"davidTip":"Resist the urge to design the whole framework in advance. Write real tests until something hurts, then fix exactly that. The suite will tell you what abstractions it needs far more reliably than a whiteboard will."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 7 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"getter-soup vs behaviour","bad":"~~~ts\n// A page object that is just locators — the test still does all the work.\nexport class LoginPage {\n  constructor(private page: Page) {}\n  get email() { return this.page.getByLabel('Email'); }\n  get password() { return this.page.getByLabel('Password'); }\n  get submit() { return this.page.getByRole('button', { name: 'Sign in' }); }\n}\n\n// test — no shorter, no safer, just indirected\nconst lp = new LoginPage(page);\nawait lp.email.fill('user@example.com');\nawait lp.password.fill('secret');\nawait lp.submit.click();\n~~~","good":"~~~ts\n// A page object that names the behaviour — the flow lives in one place.\nexport class LoginPage {\n  constructor(private page: Page) {}\n  async login(email: string, password: string) {\n    await this.page.getByLabel('Email').fill(email);\n    await this.page.getByLabel('Password').fill(password);\n    await this.page.getByRole('button', { name: 'Sign in' }).click();\n  }\n}\n\n// test — reads as intent\nconst lp = new LoginPage(page);\nawait lp.login('user@example.com', 'secret');\n~~~"},"davidTip":"A good test still reads as a story: log in, do the thing, check the outcome. If a page object makes that story clearer, keep it. If a reviewer now has to open three files to understand a five-line flow, the object is working against you, not for you.","miniChallenge":"Find a page object in a sample suite that is mostly getters. Convert two of its element getters into a single behaviour method used by the tests, and delete any getter no test needs directly."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 7 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A suite drove the full login form at the start of every one of its several hundred tests, adding a few seconds each and occasionally flaking when the auth service was slow. The team replaced it with a global setup that logged in once, saved the storage state, and had every test start authenticated through a fixture — keeping a single dedicated test that still exercised the real login form end to end. The suite lost several minutes of run time and an entire category of intermittent failures, and login itself was still genuinely tested, just once and on purpose.","visualAid":{"type":"flow","title":"The lifecycle of a fixture","steps":[{"label":"Test declares a need","detail":"It lists the fixture in its arguments, e.g. { authedPage }"},{"label":"Runner resolves the graph","detail":"Dependencies of the fixture are built first, in order"},{"label":"Setup runs","detail":"Code before await use(value) prepares the value"},{"label":"Test runs","detail":"The value is handed over during await use(value)"},{"label":"Teardown runs","detail":"Code after use() executes — guaranteed, even on failure"}]},"davidTip":"When you catch yourself copying the same three setup lines into a beforeEach across several files, that is the moment to promote them to a fixture. You gain on-demand execution, composition and guaranteed teardown for roughly the same amount of code."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 7 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"badGood":{"label":"component scoping","bad":"~~~ts\n// \"Component\" that queries the whole page — two nav regions and it breaks.\nexport class NavBar {\n  constructor(private page: Page) {}\n  async goToSection(name: string) {\n    // strict-mode violation if a footer nav also has this link\n    await this.page.getByRole('link', { name }).click();\n  }\n}\n~~~","good":"~~~ts\n// Scoped to its own root — unambiguous wherever it appears.\nexport class NavBar {\n  private root: Locator;\n  constructor(page: Page) {\n    this.root = page.getByRole('navigation', { name: 'Main' });\n  }\n  async goToSection(name: string) {\n    await this.root.getByRole('link', { name }).click();\n  }\n}\n~~~"},"davidTip":"When you feel the pull to extract something the moment you have written it twice, note the duplication in a comment and move on. Come back when the third case appears. Nine times out of ten the third case is subtly different, and having all three in front of you produces a far better abstraction than guessing from two.","miniChallenge":"Take a widget duplicated inside two page objects and lift it into a single component object scoped to its root. Point both page objects at the new component and confirm the tests still pass."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 7 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A team let their smoke suite grow unchecked — every \"important\" test earned a `@smoke` tag until the run took twenty minutes. Developers started merging without waiting for it, and a broken critical path slipped through precisely because the fast signal the tag was meant to provide no longer existed. Cutting smoke back to the dozen truly critical journeys, and moving everything else to `@regression`, restored a run people would actually wait for. The tag only protected the team while it stayed fast.","visualAid":{"type":"comparison","title":"Smoke vs regression: matching evidence to the moment","headers":["Aspect","@smoke","@regression"],"rows":[["Scope","Critical paths only","The full suite"],["Runs on","Every commit / PR","Nightly / pre-release"],["Speed","A few minutes","As long as it needs"],["Answers","Is the core still alive?","Did anything, anywhere, regress?"]]},"davidTip":"Treat the smoke suite like a fire alarm: it exists to be fast and trusted, not comprehensive. If you would hesitate to block a merge on it because it takes too long, it has stopped being a smoke suite. Curate it as ruthlessly as you would a pager rotation."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 7 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team inherited a test framework several engineers had polished into an elaborate hierarchy of base classes, generic page objects and a homegrown wrapper over Playwright. It was undeniably clever, and nobody dared touch it — every change rippled through layers no one fully held in their head, and new joiners spent a week learning the framework before writing a useful test. The team gradually dismantled it, deleting each abstraction that did not earn its place and inlining the rest. The suite got larger in line count and dramatically easier to work in, and first-week engineers started shipping real tests on day one. Elegance had been quietly trading away the maintainability the framework existed to provide.","badGood":{"label":"abstraction that earns its place vs one that does not","bad":"~~~ts\n// Wraps a familiar API in an unfamiliar one — no duplication removed.\nawait actions.clickButton('Sign in');\n~~~","good":"~~~ts\n// Names a real, reused user behaviour — earns the layer.\nawait loginPage.login('user@example.com', 'secret');\n~~~"},"davidTip":"Whenever you are about to add a layer, say out loud what pain it removes that you feel today. If the honest answer is \"it might be useful later\" or \"it is more elegant\", stop. The best framework engineers are known less for what they build than for what they refuse to build until the suite genuinely asks for it.","miniChallenge":"Find the thinnest wrapper in a framework you know — one that only renames a Playwright call — and remove it, inlining its callers. Note whether anyone could tell the tests got worse. Usually they got better."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 7 and l.lesson_number = 6;


-- ---------- seed-modern-automation-module-8-enhancements.sql ----------
-- ============================================================
-- Lesson enhancements for "modern-test-automation-bootcamp" Module 8.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/modern-automation-module8.mjs and regenerate. Run AFTER
-- lesson-enhancements-schema.sql and the lesson seeds. Idempotent.
-- ============================================================

update public.lessons l set enhancements = $ench${"industryStory":"A team's end-to-end suite took nearly forty minutes and flaked most runs. Tracing the failures showed the vast majority landed on the login screen — a step none of those tests were meant to exercise. Moving to a single setup-project login with reused storage state cut the run to under fifteen minutes and removed a whole category of flake overnight. Login was still covered — by two tests that existed to cover it, and nothing else.","visualAid":{"type":"flow","title":"Log in once, reuse everywhere","steps":[{"label":"Setup project runs first","detail":"auth.setup.ts drives the login form a single time"},{"label":"Save the session","detail":"context.storageState() writes cookies and tokens to a JSON file"},{"label":"Tests depend on setup","detail":"dependencies: [setup] guarantees it finished before they start"},{"label":"Every test starts authenticated","detail":"use.storageState loads the session into a fresh context"}]},"davidTip":"Always assert a genuine signed-in signal before calling `storageState`. Saving too early — right after the click, before the dashboard renders — captures a session that is not really logged in, and you get a baffling suite where every test fails at the first authenticated action.","miniChallenge":"Add a second dedicated UI test that logs in through the form and asserts the dashboard appears. Keep it as the only test that touches the login screen, and confirm the rest of your suite still reuses storage state."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"testing permissions","bad":"~~~ts\n// One shared session, so this only ever proves the happy path for whoever is logged in.\ntest('admin panel works', async ({ page }) => {\n  await page.goto('/admin');\n  await expect(page.getByRole('heading', { name: 'Admin' })).toBeVisible();\n});\n~~~","good":"~~~ts\n// user.spec.ts runs under the 'user' project with the standard-user state.\ntest('a standard user is refused the admin panel', async ({ page }) => {\n  const response = await page.goto('/admin');\n  expect(response?.status()).toBe(403);\n  await expect(page.getByText('You do not have access')).toBeVisible();\n});\n~~~"},"davidTip":"When a permissions test goes red, check which role's state file it loaded before you touch the application. A common false alarm is a test in the wrong project — running admin-only assertions against the standard-user session — which looks like a product bug but is really a config mistake.","miniChallenge":"Add a third identity: an unauthenticated visitor, using `storageState: { cookies: [], origins: [] }` so the project starts logged out. Write a test proving a protected page redirects that visitor to login."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A team moved all their authentication setup from the login form to a single API call and cut minutes off every run. A sprint later a redesign quietly broke the login page's submit button — and nobody noticed for days, because no automated test drove the form any more. The lesson was not \"don't use API login\"; it was \"keep one UI login test as the canary\". They added it back and it caught the next such regression the same afternoon.","visualAid":{"type":"comparison","title":"UI login vs programmatic login for setup","headers":["Aspect","UI login","Programmatic (API) login"],"rows":[["Speed","Slow — renders and drives a whole page","Fast — one HTTP request"],["Points of failure","Many (render, validation, redirect)","Few (one endpoint)"],["Best used for","Covering the login journey itself","Setup for every other test"],["Depends on the login UI","Yes","No"]]},"davidTip":"Always assert the login response succeeded before saving state. A failed API login that goes unchecked writes an empty, logged-out storage file, and then every test downstream fails at its first authenticated step — a confusing red suite whose real cause is one missing `expect(response.ok())`.","miniChallenge":"Instrument both approaches: time your UI login setup, then time the programmatic one, and record the difference. Multiply it by the number of roles you authenticate to see the real saving across a full run."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"badGood":{"label":"test data uniqueness","bad":"~~~ts\ntest('user can register', async ({ page }) => {\n  // Hardcoded email — passes once, then fails with \"email already in use\".\n  await page.getByLabel('Email').fill('test.user@example.com');\n  // ...\n});\n~~~","good":"~~~ts\nimport { makeUser } from './factories/user';\n\ntest('user can register', async ({ page }) => {\n  const user = makeUser(); // unique email every run\n  await page.getByLabel('Email').fill(user.email);\n  // ...\n});\n~~~"},"visualAid":{"type":"comparison","title":"Choosing a data source","headers":["Source","Good for","Watch out for"],"rows":[["Fixture (static)","Small, read-only values","Breaks if a test mutates or deletes it"],["Factory (generated)","Data a test creates and owns","Keep defaults realistic and readable"],["Seeded data","Shared reference data many tests read","No test should own or mutate it"]]},"davidTip":"Make a factory generate valid data by default and force the test to opt into invalid data explicitly. A test called \"rejects a malformed email\" reads far better as `makeUser({ email: 'not-an-email' })` than as a wall of hardcoded fields where the one that matters is buried.","miniChallenge":"Refactor an existing test that hardcodes a unique value to use a factory instead. Run the whole suite twice in a row and confirm the test now passes both times."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A suite was reliably green until someone reordered a couple of test files and a dozen tests started failing. The reordered tests had been quietly depending on records an earlier test created and never cleaned up — the suite only ever passed in one accidental order. Rewriting them to create and tear down their own data through fixtures, and then running with `--shuffle` in CI, made the order irrelevant and the failures vanished. The team kept the shuffle on permanently as a guard.","badGood":{"label":"cleanup that survives failure","bad":"~~~ts\ntest('cancel order', async ({ page, request }) => {\n  const order = await createOrder(request);\n  await page.goto(`/orders/${order.id}`);\n  await page.getByRole('button', { name: 'Cancel order' }).click();\n  await expect(page.getByText('Order cancelled')).toBeVisible();\n  // If any line above throws, this cleanup never runs — the order leaks.\n  await request.delete(`/api/orders/${order.id}`);\n});\n~~~","good":"~~~ts\n// Teardown lives in the fixture, after use(), so it runs even when the body throws.\nexport const test = base.extend({\n  order: async ({ request }, use) => {\n    const order = await createOrder(request);\n    await use(order);\n    await request.delete(`/api/orders/${order.id}`); // always runs\n  },\n});\n~~~"},"davidTip":"Run any test you are unsure about twice in a row on its own. If the second run fails, the test is leaving state behind or depending on state it did not create — fix that before you trust it in the suite. It is a ten-second check that catches the most common source of \"works in CI, fails locally\" arguments.","miniChallenge":"Add `--shuffle` to one CI run of your suite and see whether anything fails. Any test that only passes in a fixed order has a hidden dependency worth removing."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team committed a test account's password to a config file to \"get CI green quickly\", meaning to remove it later. The repository was mirrored to a fork before anyone did, and the credential had to be rotated across several systems once it was noticed. The fix that stuck was not just deleting the line — it was moving all secrets to the CI secret store and `.env`, adding secret scanning to the pipeline, and treating any historic leak as a rotation, not a deletion.","visualAid":{"type":"flow","title":"Where a secret lives at each stage","steps":[{"label":"Author writes code","detail":"Reads process.env only — never a literal secret in the source"},{"label":"Local run","detail":"Values come from a git-ignored .env, loaded with dotenv"},{"label":"Committed to git","detail":"Only .env.example (keys, dummy values) is ever committed"},{"label":"CI run","detail":"The pipeline injects the same variable names from its encrypted secret store"}]},"davidTip":"Commit a `.env.example` from day one. It documents exactly which variables the suite needs without exposing a single real value, and it turns \"the tests fail on a fresh clone with a cryptic error\" into \"copy `.env.example` to `.env` and fill in the blanks\" — the difference between an hour of onboarding friction and five minutes.","miniChallenge":"Add a guard to your config that throws a clear error if a required secret is missing, naming the variable and pointing at `.env.example`. A precise \"USER_PASSWORD is not set\" beats a confusing login failure three steps later."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 8 and l.lesson_number = 6;


-- ---------- seed-modern-automation-module-9-enhancements.sql ----------
-- ============================================================
-- Lesson enhancements for "modern-test-automation-bootcamp" Module 9.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/modern-automation-module9.mjs and regenerate. Run AFTER
-- lesson-enhancements-schema.sql and the lesson seeds. Idempotent.
-- ============================================================

update public.lessons l set enhancements = $ench${"industryStory":"A team had a two-hour UI suite that re-checked dozens of validation rules by filling and submitting forms. Every rule change meant a slow, flaky test to maintain. When they moved the rules down to API tests — one request each — the suite that covered them ran in under a minute, and the handful of UI tests that remained only proved the journey and that errors reached the screen. The pyramid was right-side-up again, and the pipeline stopped being the bottleneck.","visualAid":{"type":"comparison","title":"The same rule: UI test vs API test","headers":["Aspect","Through the UI","At the API"],"rows":[["Speed","Seconds per case","Milliseconds per case"],["Stability","Timing, layout, widgets","Deterministic response"],["Coverage","Only what a user can reach","Every path and edge case"],["Best used for","The journey is displayed","The rule is enforced"]]},"davidTip":"Before writing an end-to-end test, ask whether the thing you want to prove is really about the screen or about the system. If it is about the system, it almost always belongs one layer down — cheaper, steadier and more thorough at the API."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 9 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"building a request","bad":"~~~ts\n// Manual query string, hand-stringified body, header set by hand.\nconst res = await request.post(\n  '/api/orders?status=open&page=1',\n  {\n    headers: { 'Content-Type': 'application/json' },\n    data: JSON.stringify({ sku: 'KBD-01', quantity: 2 }),\n  },\n);\n~~~","good":"~~~ts\n// Let Playwright encode params and serialise the JSON body.\nconst res = await request.post('/api/orders', {\n  params: { status: 'open', page: 1 },\n  data: { sku: 'KBD-01', quantity: 2 },\n});\n~~~"},"davidTip":"Read the `APIRequestContext` methods once, properly, before writing your first suite. Most confused API tests come from not knowing that `data`, `params` and `form` already exist — people reinvent them badly and the tests get harder to read for no reason.","miniChallenge":"Take a request you wrote with a manual query string and rewrite it to use `params`. Confirm the response is identical, then try sending the same body as `form` instead of `data` and observe how the request changes."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 9 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"badGood":{"label":"strength of an API assertion","bad":"~~~ts\nconst response = await request.post('/api/orders', {\n  data: { sku: 'KBD-01', quantity: 2 },\n});\n// Proves the endpoint answered — nothing about whether it answered correctly.\nexpect(response).toBeOK();\n~~~","good":"~~~ts\nconst response = await request.post('/api/orders', {\n  data: { sku: 'KBD-01', quantity: 2 },\n});\nexpect(response.status()).toBe(201);\nconst order = await response.json();\nexpect(order).toMatchObject({ sku: 'KBD-01', quantity: 2, status: 'pending' });\nexpect(typeof order.id).toBe('string');\n~~~"},"visualAid":{"type":"comparison","title":"Choosing the right status assertion","headers":["Situation","Assertion","Why"],"rows":[["Any success is fine","expect(response).toBeOK()","Accepts any 2xx, prints the body on failure"],["Creation","status() === 201","201 is the contract, not just any 2xx"],["Not found","status() === 404","toBeOK would be the wrong assertion"],["Forbidden vs missing","status() === 403 / 404","The exact code is the behaviour under test"]]},"davidTip":"In review, treat any API test whose only assertion is `toBeOK()` the way you would treat a UI test whose only assertion is `toBeVisible()` on a container: unfinished. Ask \"if the response quietly changed shape, would this go red?\" If not, the contract is not really being tested."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 9 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A team's API suite logged in at the start of every test. As the suite grew past a few hundred tests, the auth service started rate-limiting the CI runner, and builds failed for reasons that had nothing to do with the code under test. Moving the login into a single setup step that produced a shared authenticated context cut thousands of redundant calls, and the flakiness that everyone had been blaming on \"the network\" simply vanished.","davidTip":"Always write the `401` and `403` tests alongside the happy path. The authorised case tells you the feature works for the right people; the rejected cases tell you it does not work for the wrong ones — and on anything touching data or money, that second guarantee is the one that keeps you out of trouble.","miniChallenge":"Add a test that logs in with valid credentials, then makes a request with a deliberately corrupted token, and assert the API responds with `401`. This proves the endpoint actually validates the token rather than merely checking the header is present."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 9 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A team's checkout end-to-end tests were the slowest and flakiest in the suite, because each one registered a user and walked the full basket-to-payment flow just to reach the screen it wanted to check. Rewriting them to seed the user and the order through the API, and driving only the final verification through the browser, cut their runtime by most of it and stopped the intermittent failures on setup screens that had nothing to do with checkout. The tests that remained failed only when the thing they tested actually broke.","visualAid":{"type":"flow","title":"A hybrid end-to-end test","steps":[{"label":"Arrange (API)","detail":"Create the user, order or state in one fast call"},{"label":"Authenticate (API)","detail":"Seed the session via storageState — no login form"},{"label":"Act (UI)","detail":"Drive only the interaction under test in the browser"},{"label":"Assert (UI)","detail":"Verify the rendered outcome a user would see"},{"label":"Tear down (API)","detail":"Delete what you created so the next run is clean"}]},"davidTip":"The rule of thumb: drive through the UI only the thing you are actually testing. Everything before and after it — setup, login, cleanup — should go through the API. A good end-to-end test reads like a single sentence of UI surrounded by fast, invisible plumbing."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 9 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team proudly refactored their API suite so every spec was a short, clean list of helper calls. It read beautifully — until a real bug shipped that the tests should have caught. The assertions had all been pulled into the helpers, and some helpers had quietly stopped asserting anything meaningful during the refactor. Nobody noticed, because the specs no longer showed what was being checked. They moved the defining assertions back into the tests, and readability cost them nothing while trust returned immediately.","badGood":{"label":"where the assertion lives","bad":"~~~ts\n// Helper hides the assertion; the spec proves nothing a reader can see.\nasync function assertOrderCreated(api, data) {\n  const res = await api.post('/api/orders', { data });\n  expect(res.status()).toBe(201);\n  expect(await res.json()).toMatchObject(data);\n}\n\ntest('create order', async ({ api }) => {\n  await assertOrderCreated(api, { sku: 'KBD-01', quantity: 2 });\n});\n~~~","good":"~~~ts\n// Helper does the plumbing; the test states what it verifies.\nasync function createOrder(api, data) {\n  const res = await api.post('/api/orders', { data });\n  expect(res.status()).toBe(201);\n  return res.json();\n}\n\ntest('a created order comes back with the fields we sent', async ({ api }) => {\n  const order = await createOrder(api, { sku: 'KBD-01', quantity: 2 });\n  expect(order).toMatchObject({ sku: 'KBD-01', quantity: 2 });\n});\n~~~"},"visualAid":{"type":"comparison","title":"request fixture vs hand-built context","headers":["Need","request fixture","newContext"],"rows":[["Fresh, isolated per test","Yes, automatic","Manual"],["Shared auth across tests","No","Yes, log in once"],["Different baseURL / headers","From config only","Set per context"],["You manage disposal","No, handled for you","Yes, always dispose()"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 9 and l.lesson_number = 6;


