update public.lessons l set enhancements = $ench${"industryStory":"A team had a healthy-looking Playwright suite that lived on developers' machines. It was run \"before merging\" — in theory. Over a busy quarter the shared environment kept breaking in ways the suite would have caught, and each time the answer was the same: the person who merged had not run it. The tests were fine; the process around them was optional. When the team finally moved the suite into GitHub Actions on every pull request and blocked merges on red, the environment-break tickets dried up within a fortnight. Nothing about the tests changed — only that they now ran automatically and their result could stop a merge.","visualAid":{"type":"comparison","title":"Local runs versus CI runs","headers":["Property","Run locally by hand","Run in CI on every change"],"rows":[["When it runs","When someone remembers","Automatically, every push and PR"],["Environment","Your machine, your state","Clean runner, repeatable"],["Who sees red","Only the person running it","Everyone, on the pull request"],["Can it block a merge?","No","Yes, with branch protection"]]},"davidTip":"Optimise the pull-request run for speed above all else early on — a suite that reports in two minutes gets trusted and watched; one that takes twenty gets bypassed. You can add slower, deeper runs on a schedule later. The fast per-change run is the one that changes behaviour."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 12 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"a fragile first workflow vs a solid one","bad":"~~~yaml\n# Unpinned actions, non-reproducible install, no browser install, no Node version.\non: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout\n      - run: npm install\n      - run: npx playwright test\n~~~","good":"~~~yaml\non:\n  push:\n    branches: [main]\n  pull_request:\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n      - run: npm ci\n      - run: npx playwright install --with-deps\n      - run: npx playwright test\n~~~"},"davidTip":"You do not have to memorise this YAML — running `npm init playwright@latest` scaffolds a workflow file for you. But read what it generates line by line rather than pasting it blind. Understanding the triggers, the job and each step is what lets you debug it at 9am when the pull-request check is mysteriously red.","visualAid":{"type":"flow","title":"What a job does on a clean runner","steps":[{"label":"Runner starts empty","detail":"A fresh Ubuntu VM: no code, no Node modules, no browsers."},{"label":"Check out the code","detail":"actions/checkout brings your repository onto the runner."},{"label":"Set up Node","detail":"actions/setup-node installs the pinned version."},{"label":"Install dependencies","detail":"npm ci installs exactly what the lockfile specifies."},{"label":"Run the suite","detail":"npx playwright test — its exit code becomes the check result."}]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 12 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A team added a hand-rolled cache of the Playwright browsers folder to shave a minute off each run. It worked — until they bumped the Playwright version. The cache key had not included the version, so runners kept restoring the old browsers while the code expected the new ones, and tests failed with launch errors that looked exactly like a product bug. Half a day went into chasing it before someone noticed the cache. They fixed it by putting the resolved Playwright version in the key and re-running `install --with-deps` on a miss, but the lesson stuck: cache browsers only deliberately, and always version the key.","davidTip":"When a CI run fails with a missing shared-library error (something like a `.so` file it cannot find) and the same test passes locally, your first suspect is a missing `--with-deps`. Nine times out of ten the install step is downloading browsers but not their OS libraries. Fix the install step before you go anywhere near the test itself.","visualAid":{"type":"comparison","title":"What to cache in a Playwright CI job","headers":["Thing","Cache it?","How to key it"],"rows":[["npm downloads","Yes — cheap, safe","Built in: cache: npm on setup-node"],["Browser binaries","Only if measured as a bottleneck","Must include the exact Playwright version"],["node_modules directly","Prefer not to","Fragile across Node/OS; use the npm cache instead"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 12 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"badGood":{"label":"upload only on success vs upload on failure too","bad":"~~~yaml\n# Skipped whenever the test step fails — you lose the report exactly when you need it.\n- name: Upload report\n  uses: actions/upload-artifact@v4\n  with:\n    name: playwright-report\n    path: playwright-report/\n~~~","good":"~~~yaml\n# Uploads whether tests passed or failed; skips only on a cancelled run.\n- name: Upload report\n  uses: actions/upload-artifact@v4\n  if: ${{ !cancelled() }}\n  with:\n    name: playwright-report\n    path: playwright-report/\n    retention-days: 7\n~~~"},"davidTip":"The trace viewer is the single most valuable thing you get out of CI, and most teams under-use it. When someone says \"the CI failure won't reproduce\", the answer is almost always \"download the trace from that run and open it\" — you get the exact DOM and network state from the failing run, not an approximation. Make opening the trace the first move on any CI-only failure, not the last resort.","miniChallenge":"Add a second artifact upload that captures `test-results/` (videos and raw traces) only `if: failure()`, and compare it with the always-uploaded HTML report. Decide which you would actually keep on a busy repository, and note why — storage and retention are real costs on a suite that runs hundreds of times a day."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 12 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A team was proud of requiring their full cross-browser suite on every pull request — until it turned out that suite had a handful of intermittently flaky tests. Merges started stalling on random reds, and the team's fix was cultural rather than technical: everyone learned to click \"re-run jobs\" until it went green. Then a genuine regression came through, went red, got re-run out of habit, went green on a lucky retry, and merged. The gate had trained them to ignore itself. They split the suite — a fast, stable subset became the required gate, the full cross-browser run moved to a nightly non-blocking job — and made fixing any flake in the gated subset a priority-one task. Red meant stop again.","visualAid":{"type":"comparison","title":"What to put on the merge gate","headers":["Check","Gate on it?","Why"],"rows":[["Fast stable PR suite","Yes","Quick, meaningful, trustworthy red"],["Lint and type checks","Yes","Cheap, deterministic, always-real failures"],["Flaky suite","No — fix it first","Random red trains the team to bypass the gate"],["Slow nightly cross-browser run","No — inform only","Too slow to block every merge; run on a schedule"]]},"davidTip":"The health of your gate is measured by one number nobody puts on a dashboard: how often people re-run a required check without reading why it failed. If that is happening at all, your gate has a flakiness problem that is quietly costing you every real failure it will ever catch. Treat \"we just re-run it\" as an incident, not a workaround."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 12 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"badGood":{"label":"sharding without merging vs sharding with a merge job","bad":"~~~yaml\n# Four shards, four separate HTML reports, no way to see the suite as a whole.\nstrategy:\n  matrix:\n    shard: [1, 2, 3, 4]\nsteps:\n  - run: npx playwright test --shard=${{ matrix.shard }}/4\n  # each shard writes its own playwright-report/ — fragmented and unmergeable\n~~~","good":"~~~yaml\n# Shards emit blob reports; a later job merges them into one HTML report.\nstrategy:\n  fail-fast: false\n  matrix:\n    shard: [1, 2, 3, 4]\nsteps:\n  - run: npx playwright test --shard=${{ matrix.shard }}/4   # reporter: 'blob' in config\n  - uses: actions/upload-artifact@v4\n    if: ${{ !cancelled() }}\n    with:\n      name: blob-report-${{ matrix.shard }}\n      path: blob-report/\n# ...then a separate merge-report job runs: npx playwright merge-reports --reporter=html\n~~~"},"davidTip":"Sharding is a speed tool, so let the numbers decide the shard count, not instinct. Time your single-runner suite, pick the smallest shard count that brings the gate back under your target (a few minutes), and stop there. Every extra shard adds runner cost and a bit of scheduling overhead, and beyond a point you are paying for parallelism the suite is not big enough to use.","visualAid":{"type":"flow","title":"Sharded run with a merged report","steps":[{"label":"Matrix fans out","detail":"One job definition becomes N parallel shard jobs."},{"label":"Each shard runs its slice","detail":"npx playwright test --shard=i/N, reporter set to blob."},{"label":"Shards upload blob reports","detail":"Each uploads blob-report/ as a distinctly named artifact."},{"label":"Merge job waits (needs:)","detail":"A dependent job downloads the blob report from every shard."},{"label":"One HTML report","detail":"merge-reports --reporter=html stitches the blobs into one."}]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 12 and l.lesson_number = 6;


-- ---------- seed-modern-automation-module-13-enhancements.sql ----------
-- ============================================================
-- Lesson enhancements for "modern-test-automation-bootcamp" Module 13.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/modern-automation-module13.mjs and regenerate. Run AFTER
-- lesson-enhancements-schema.sql and the lesson seeds. Idempotent.
