update public.lessons l set enhancements = $ench${"badGood":{"label":"one reporter for all vs audience-appropriate reporters","bad":"~~~ts\n// A single reporter used everywhere — verbose locally, and no artefact to investigate in CI.\nexport default defineConfig({\n  reporter: 'list',\n});\n~~~","good":"~~~ts\n// Human-facing and machine-facing reporters, switched by environment.\nexport default defineConfig({\n  reporter: process.env.CI\n    ? [['dot'], ['html', { open: 'never' }], ['junit', { outputFile: 'results.xml' }]]\n    : [['list'], ['html', { open: 'on-failure' }]],\n});\n~~~"},"davidTip":"Set `open: 'never'` for the HTML reporter in CI explicitly — the default tries to open a browser, which either hangs a headless agent or prints a confusing error. Publish the `playwright-report` folder as an artefact and link it from the build summary so a failing run is one click from a full report.","visualAid":{"type":"comparison","title":"Choosing a reporter by audience","headers":["Reporter","Reads like","Best for"],"rows":[["list","One line per test","Watching a local run"],["dot","One char per test","Compact CI console logs"],["html","A web page with traces","A human investigating a failure"],["junit","XML","CI platforms showing native pass/fail"],["json","A data document","Dashboards and custom tooling"],["blob","An opaque bundle","Merging sharded runs into one report"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 13 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A team spent a fortnight blaming \"flaky infrastructure\" for a login test that failed roughly once a day in CI and never locally. When they finally enabled `trace: 'on-first-retry'` and opened a captured trace, the DOM snapshot before the failing click showed a promotional modal that appeared only for accounts created that day — a date-dependent banner that intercepted the click. The cause was in plain sight in the trace the whole time; the fortnight of guesswork was simply the cost of not capturing evidence. After that the rule was non-negotiable: every failing test in CI attaches a trace, and no flake is triaged until someone has opened it.","davidTip":"`trace: 'on-first-retry'` is the setting you want in almost every real project: it costs nothing on passing tests and gives you a full recording of exactly the runs that failed. Reach for `trace: 'on'` only in a short, deliberate debugging session on a specific test — never leave it on for the whole suite.","visualAid":{"type":"comparison","title":"Failure artefacts and when to use each","headers":["Artefact","What it shows","Config value"],"rows":[["Screenshot","A still of the end state","screenshot: 'only-on-failure'"],["Video","The whole run as it played","video: 'retain-on-failure'"],["Trace","Actions, DOM snapshots, network, console","trace: 'on-first-retry'"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 13 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"badGood":{"label":"guess-and-repair vs the method","bad":"~~~ts\n// A blind timing patch: papers over the symptom, understands nothing, stays flaky.\nawait page.waitForTimeout(3000);            // hope three seconds is enough\nawait page.getByRole('button', { name: 'Place order' }).click();\n~~~","good":"~~~ts\n// The trace showed the button enables only after address validation resolves.\n// Assert the real precondition — deterministic, and self-documenting.\nconst placeOrder = page.getByRole('button', { name: 'Place order' });\nawait expect(placeOrder).toBeEnabled();\nawait placeOrder.click();\n~~~"},"davidTip":"`npx playwright test --last-failed` re-runs only the tests that failed last time, and `--repeat-each=N` runs each the given number of times. Together they are your debugging loop: reproduce with `--last-failed --headed`, then prove the fix with `--repeat-each`. Tightening this loop is worth more than any single clever fix.","visualAid":{"type":"flow","title":"The four-step debugging method","steps":[{"label":"Read the error","detail":"Whole message and call log; name the type — timeout, assertion, or app error."},{"label":"Reproduce it","detail":"Run the one test headed locally, or open the trace of the failing CI run."},{"label":"Use the trace","detail":"Inspect the DOM snapshot, network and console at the failing action."},{"label":"Bisect","detail":"Test or app? When did it start? Which step? Then confirm the fix by re-running."}]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 13 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A team's end-to-end suite grew to fifteen hundred tests, of which perhaps forty flaked on any given run. People stopped reading the results — a red build meant \"re-run it\", not \"investigate\". The suite was technically enormous and practically useless, and a genuine checkout regression sailed through because its failure looked like just more noise. The recovery was unglamorous: they quarantined every flake with a ticket, deleted two hundred dead and duplicate tests, tagged the rest with owning teams, and instituted a fortnightly health review. The suite shrank and got faster, and — the point — people started trusting red again. Trust, not count, was what they had actually lost.","davidTip":"A quarantined test needs an expiry, not just a skip. Put a review date in the `test.fixme` reason and run a scheduled `--grep @quarantine` job so the parked tests stay visible. A quarantine with no deadline is just a slow deletion nobody admitted to.","visualAid":{"type":"comparison","title":"Silent skip versus visible quarantine","headers":["Aspect","Silent test.skip","Visible quarantine"],"rows":[["Breaks the main build","No","No"],["Coverage loss is tracked","No","Yes — ticket and owner"],["Has a review date","No","Yes"],["Likely to be fixed","Rarely — forgotten","Yes — on someone’s list"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 13 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A tester proudly reported a release candidate as \"100% green, all tests passing, ready to go\", and the team shipped. Within hours users hit a broken password-reset flow — one that had never been automated, so no test had ever exercised it. The run had been perfectly honest about what it checked; the *reporting* had turned bounded evidence into a blanket guarantee, and when reality diverged it was testing's credibility that took the hit. The lasting fix was not more tests but better communication: every release summary from then on led with failures, named the untested flows explicitly, and stated in one line what the green did and did not cover. The green stopped being oversold, and — the point — people started trusting it again.","davidTip":"Get in the habit of ending every result report with one sentence that scopes the green: \"these flows passed under test conditions; here is what we did not cover.\" It costs you a line and buys you credibility, because the caveat is what proves you are reporting evidence honestly rather than selling reassurance.","visualAid":{"type":"comparison","title":"What a green run does and does not prove","headers":["A green run IS evidence that…","A green run is NOT proof that…"],"rows":[["The behaviours you automated worked this run","The product is good or users will be happy"],["The risks you chose to check did not fire","Risks you did not automate are absent"],["The app behaved under your test conditions","It behaves under real production conditions"],["Known regressions did not reappear","Untested and unknown paths work"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 13 and l.lesson_number = 5;


-- ---------- seed-modern-automation-module-14-enhancements.sql ----------
-- ============================================================
-- Lesson enhancements for "modern-test-automation-bootcamp" Module 14.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/modern-automation-module14.mjs and regenerate. Run AFTER
-- lesson-enhancements-schema.sql and the lesson seeds. Idempotent.
-- ============================================================

update public.lessons l set enhancements = $ench${"industryStory":"A team under deadline pressure started generating Playwright specs wholesale and merging them once they went green. Coverage numbers climbed and everyone felt fast — until a release where a broken checkout shipped behind a wall of passing tests. Investigation showed dozens of the generated tests asserted only that a page loaded or a URL changed, never that the feature worked. The tool had optimised for \"passes\", not \"proves\". The team did not stop using AI; they changed the rule to \"AI drafts, a human reviews and strengthens every assertion before merge\", and their green suite started meaning something again.","davidTip":"When you pick up an AI assistant for the first time, deliberately ask it to do something you already know the answer to — a test for a feature you understand inside out. Watching where it guesses, invents and hand-waves on familiar ground teaches you exactly how much to trust it on unfamiliar ground. Calibrate on the known before you rely on it for the unknown.","visualAid":{"type":"comparison","title":"Good and bad jobs for an AI assistant in test automation","headers":["Task","AI is good at it because…","AI is bad at it because…"],"rows":[["Scaffolding a page object","It is repetitive structure","—"],["Explaining a stack trace","It has read millions of them","—"],["Choosing what to test","—","It cannot judge your risk"],["Picking real selectors","—","It has never seen your app"],["Writing strong assertions","—","Passing is easy; proving is hard"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"context-free prompt vs planned, grounded prompt","bad":"~~~text\nPrompt: \"write a playwright test for the search feature\"\n→ AI guesses the input selector, the results selector, and what \"working\"\n  means. The draft asserts only that some results element is visible —\n  it never checks the results actually match the query.\n~~~","good":"~~~text\nPrompt with context + plan:\n\"Context: the search box has label 'Search products'; results render as a\nlist of <article> with an <h3> product name. Risk: if search returns\nirrelevant results customers cannot find products. Patterns: getByRole,\nour `shopper` fixture, match spec X.\nPlan: given a shopper, when they search 'tent', then every visible result\nname contains 'tent' (case-insensitive) and there is at least one result.\"\n→ Draft asserts the results are relevant, not merely present.\n~~~"},"davidTip":"Write your arrange-act-assert plan as a comment at the top of the empty spec file, then ask the assistant to implement it. The plan stays in the file as documentation of intent, the AI has a precise target, and the next reviewer can check the code against the plan in seconds. It is the cheapest way to keep human intent and generated code side by side."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"miniChallenge":"Ask the assistant to generate a test-data builder for your domain — say, a function that produces a valid order with sensible defaults and overridable fields. Then deliberately hunt for a domain rule it got wrong (a total that does not match line items, a status that cannot follow another). Fixing that is a concrete example of the human supplying the domain knowledge the AI lacks.","davidTip":"When a generated locator fails, resist the urge to ask the AI to \"try another selector\" — it will just guess again. Instead open Playwright’s codegen or the trace viewer, find the real accessible name yourself, and feed *that* back. One piece of real evidence ends the guessing loop that ten more prompts would prolong.","visualAid":{"type":"flow","title":"The generate-run-refine loop","steps":[{"label":"Prompt with context","detail":"Plan plus real element names, ask for role-based locators."},{"label":"Generate a small piece","detail":"One spec or page object, not the whole suite."},{"label":"Run against the real app","detail":"The app is the source of truth, not the model."},{"label":"Feed evidence back","detail":"Real labels and failures, not another guess."},{"label":"Refine locators and assertions","detail":"These two you own; keep them under your control."}]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A team hit an intermittent failure and the assistant confidently diagnosed a timing race, suggesting a fixed wait. They added it; the flakiness moved but did not go away. Only when someone opened the trace did the real cause appear — a locator matching two elements — which no amount of waiting would fix. They removed the wait, tightened the locator, and the flakiness vanished. The lesson they drew was not \"the AI is useless\" but \"the AI gives you a lead and the trace gives you the truth\"; from then on every AI failure diagnosis was checked against a trace before anyone changed code.","badGood":{"label":"acting on a plausible explanation vs verifying it","bad":"~~~ts\n// AI said \"it's a race, add a wait\" — symptom patched, cause unknown.\nawait page.getByRole('button', { name: 'Save' }).click();\nawait page.waitForTimeout(1000); // guess dressed up as a fix\nawait expect(page.getByText('Saved')).toBeVisible(); // still ambiguous\n~~~","good":"~~~ts\n// Trace showed strict-mode ambiguity, not a race. Fix the real cause.\nawait page.getByRole('button', { name: 'Save' }).click();\nawait expect(page.getByRole('status')).toHaveText('Saved'); // one element, web-first wait\n~~~"}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"badGood":{"label":"green-but-wrong vs a test that proves the outcome","bad":"~~~ts\n// Named for saving a profile, but asserts only that a button was clickable.\ntest('profile changes are saved', async ({ page }) => {\n  await page.goto('/profile');\n  await page.getByLabel('Display name').fill('Ada Lovelace');\n  await page.getByRole('button', { name: 'Save' }).click();\n  await expect(page.getByRole('button', { name: 'Save' })).toBeVisible(); // green, proves nothing\n});\n~~~","good":"~~~ts\n// Asserts the change actually persisted — the outcome the name promises.\ntest('profile changes are saved and persist after reload', async ({ page }) => {\n  await page.goto('/profile');\n  await page.getByLabel('Display name').fill('Ada Lovelace');\n  await page.getByRole('button', { name: 'Save' }).click();\n  await expect(page.getByRole('status')).toHaveText('Profile saved');\n\n  await page.reload(); // prove it persisted, not just that a toast appeared\n  await expect(page.getByLabel('Display name')).toHaveValue('Ada Lovelace');\n});\n~~~"},"davidTip":"Keep a personal checklist for reviewing generated tests and run every one through it: does every API call exist, does every selector resolve to the intended element, and would each assertion fail if the feature broke? The discipline of a literal checklist matters more with AI output than with your own, because AI code arrives looking finished and its confidence is uniform whether it is right or wrong.","visualAid":{"type":"comparison","title":"Four failure modes of AI-generated tests and how to catch each","headers":["Failure mode","What it looks like","How you catch it"],"rows":[["Hallucinated API","A method or option Playwright never had","Type-check and run; verify against the docs"],["Invented selector","A #id or data-testid not in your app","Confirm it resolves to the intended element"],["Weak assertion","Checks a URL or visibility, not the outcome","Ask: would it fail if the feature broke?"],["Asserts nothing","A flow with no meaningful check","Break the feature; see if it stays green"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team debugging a payment integration pasted a failing request, complete with a live gateway key, into an external assistant to get quick help. The fix worked and nobody thought more of it — until a routine security review flagged the key as potentially exposed and it had to be rotated across every service that used it, an afternoon of scramble that a one-line synthetic placeholder would have avoided entirely. The team adopted two rules the same week: secrets never leave configuration, and any secret that touches an external tool is rotated on sight. The help the AI gave was real; so was the avoidable risk, and the difference was entirely in what was pasted.","davidTip":"Build a tiny \"sanitise before you paste\" reflex: before any snippet goes into an external tool, scan it for a key, a real email, a real card, a customer name, or anything proprietary, and swap each for a synthetic equivalent. It takes seconds and it becomes automatic. The engineers who never leak data are not the cautious ones who agonise each time — they are the ones for whom sanitising is muscle memory.","visualAid":{"type":"comparison","title":"What to share with an external AI tool — and what never to","headers":["Category","Never paste the real thing","Safe stand-in to share instead"],"rows":[["Secrets","API keys, tokens, passwords","process.env references; described, not shown"],["Personal data","Real names, emails, cards","Synthetic-but-faithful fake values"],["Proprietary code","Whole confidential modules","The minimal non-sensitive slice"],["The problem shape","—","Structure, error type, behaviour — always fine"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 6;

update public.lessons l set enhancements = $ench${"davidTip":"Print your AI-use rules and keep them where you will see them, because the moment you need them is the moment you are least inclined to follow them — the end of a long day with a green generated draft and a deadline. A rule you decided calmly in advance is far easier to keep than a judgement you have to make under pressure. That is the entire reason to write them down rather than \"just remember\".","visualAid":{"type":"flow","title":"The plan → generate → review → verify loop","steps":[{"label":"Plan (human)","detail":"Decide what the test must prove and the risk. The AI cannot."},{"label":"Generate (AI)","detail":"Draft fast from your plan and real context."},{"label":"Review (human)","detail":"Hunt hallucinated APIs, invented selectors, weak assertions."},{"label":"Verify (human)","detail":"Run against the real app; confirm it fails when the feature breaks."},{"label":"Own it (human)","detail":"Commit under your name means you read, verified and stand behind it."}]},"miniChallenge":"Take a test a teammate or an earlier you generated and merged, and run it back through the full loop as if reviewing it fresh. Note anything the original process missed — a weak assertion, an unverified locator, a missing plan. The gap between \"was merged\" and \"would survive the loop\" is a concrete measure of how much the workflow protects you."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 7;


