update public.lessons l set enhancements = $ench${"badGood":{"label":"strategy after the fact vs strategy first","bad":"~~~text\nApproach: open the editor, start writing UI tests for whatever screen is open,\nadd more when a bug is found, and at the end write a \"strategy\" that describes\nthe pile that resulted. Every rule is checked through the browser because that\nwas the first tool to hand. Nobody can say what a green run proves.\n~~~","good":"~~~text\nApproach: write docs/automation-strategy.md first. Decide payment and auth are\nhighest risk and get real UI coverage; validation rules go to fast API tests;\nUI tests set up state via API and assert one journey step each. Exclusions are\nnamed. A green smoke run has a written, defensible claim. Then the code follows.\n~~~"},"davidTip":"When you are unsure whether something belongs at UI or API level, ask what would break if you got it wrong. If a broken backend rule shows up as a wrong number on a screen, an API test finds it faster and tells you exactly where. Reserve the UI test for \"can a human actually get through this journey\" — that is the thing only a UI test can prove.","visualAid":{"type":"comparison","title":"Choosing the level for a piece of coverage","headers":["What you are checking","Best level","Why"],"rows":[["A backend validation or business rule","API","Fast, precise, stable; points straight at the logic"],["A user can complete a journey","UI","Only a real browser journey proves this"],["State needed before a UI assertion","API setup","Instant and reliable versus slow clicking"],["Error and edge-case handling","API (mostly)","Cheap to trigger every branch directly"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 16 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"Consider two engineers given the same capstone. One spent a week building an elegant base-page hierarchy, a custom config loader and a plugin system — none of which had run in CI by the deadline, and half of which had a single caller. The other had a plainer repo: one composed fixture, a setup project for auth, thirty focused tests, and a green pipeline from day three. In review, the second repo was the one people wanted to extend, because everything in it earned its place and it demonstrably worked where it would actually run. Sophistication is building exactly what the tests need and no more.","davidTip":"Get authentication working end to end before you write your second test. It touches everything — every UI test assumes a session, the config wires storage state into every project, and CI has to log in without a human. Solving it early makes the rest of the build a straight line; solving it late means retrofitting a session into tests that already assumed one.","miniChallenge":"Once your slice is green in CI, deliberately break authentication (revoke the test token or point `BASE_URL` at the wrong environment) and watch how the pipeline fails. A good failure names the problem clearly in the report and trace; if yours is a cryptic timeout, improve the setup project's error handling so future-you is not debugging blind."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 16 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"badGood":{"label":"overclaiming vs honest framing","bad":"~~~text\n\"Automation framework I built and maintained in production for a fintech client,\ncovering their full regression suite used by a team of eight over two years.\"\n\n(None of it true. One question — \"which fintech, and what was the hardest flake\nyou fixed in those two years?\" — and the whole story, and your credibility, fold.)\n~~~","good":"~~~text\n\"A capstone automation project I built independently to demonstrate a\nproduction-style Playwright + TypeScript setup: UI and API coverage, auth via\nstorage state, CI, and a written strategy. It is study and practice, not client\nwork — and I can walk you through every decision in it.\"\n\n(True, specific, and it invites exactly the conversation you are prepared for.)\n~~~"},"davidTip":"The strongest thing you can do in an interview is volunteer a limitation before you are asked. \"Here's what this suite deliberately doesn't cover, and why\" tells the interviewer you think in trade-offs, not absolutes — and it is the single clearest signal of a senior mindset. Practise saying your exclusions out loud until they sound like judgement, which is what they are.","visualAid":{"type":"flow","title":"Turning a working repo into defensible evidence","steps":[{"label":"Can a stranger run it?","detail":"A README that gets them to a green smoke run without asking you."},{"label":"Can they understand the coverage?","detail":"A strategy document: levels, risk, exclusions, the green-run claim."},{"label":"Do they know the gaps?","detail":"An honest limitations section — what the suite does not prove."},{"label":"Do they trust how it was built?","detail":"A specific AI-usage declaration; what you drove versus assisted."},{"label":"Is it framed truthfully?","detail":"A capstone project you built to show skill — never commercial experience you have not had."}]}}$ench$::jsonb
