q10 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An integration test sits in the middle layer of the pyramid. What trade-off does it represent compared with a unit test?$qz$, 'multiple_choice', 10 from newq returning id),
a10 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q10.id, v.t, v.c from q10, (values ($qz$It is faster and more isolated than a unit test$qz$, false), ($qz$It gives more confidence that components work together, at the cost of being slower and harder to diagnose when it fails$qz$, true), ($qz$It replaces the need for any unit tests$qz$, false), ($qz$It has no downsides over a unit test$qz$, false)) as v(t, c) returning question_id),
q11 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Thinking like an automation engineer, which mindset best describes a healthy relationship with your own suite?$qz$, 'multiple_choice', 11 from newq returning id),
