a9 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q9.id, v.t, v.c from q9, (values ($qz$Fixtures declare a test’s needs by parameter and guarantee setup and teardown around the test, whereas a manually-called helper leaves teardown and ordering to the author to remember$qz$, true), ($qz$There is no difference; fixtures are only syntactic sugar over calling a helper and behave identically on failure$qz$, false), ($qz$Helper functions run in parallel automatically while fixtures always force serial execution$qz$, false), ($qz$Fixtures can only provide primitive values, so any object such as a page must come from a helper$qz$, false)) as v(t, c) returning question_id),
q10 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A team decides every spec must extend a deep inheritance chain: `BasePage` → `AuthenticatedPage` → `DashboardPage` → `ReportsPage`. Six months on, changes to `BasePage` break unrelated pages. What does this illustrate?$qz$, 'multiple_choice', 10 from newq returning id),
a10 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q10.id, v.t, v.c from q10, (values ($qz$Deep inheritance couples unrelated pages through a shared base, so a change high in the chain ripples widely; composition of small components is usually the more flexible choice$qz$, true), ($qz$Inheritance is never usable in test frameworks and the language should forbid it$qz$, false), ($qz$The chain is simply one level too short; adding another base class would have prevented the breakage$qz$, false), ($qz$The breakage proves the pages were not tagged correctly, which is the real root cause$qz$, false)) as v(t, c) returning question_id),
q11 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You are asked to justify a proposed component object for a reusable date-picker that appears on eight different pages. Which justification is soundest?$qz$, 'multiple_choice', 11 from newq returning id),
a11 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q11.id, v.t, v.c from q11, (values ($qz$The widget is duplicated across many pages, so a component object gives one place to change its interactions and stops eight copies drifting apart$qz$, true), ($qz$Every widget should have a component object regardless of how many places it appears, for consistency$qz$, false), ($qz$A date-picker is complex, and complex widgets must always be abstracted even if they appear only once$qz$, false), ($qz$Component objects make tests run faster, which is the primary reason to introduce one$qz$, false)) as v(t, c) returning question_id)
