q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A setup project logs in once through the UI and calls `await page.context().storageState({ path: 'auth/user.json' })`. Later tests load that file as `storageState`. What has this achieved?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$It captured the authenticated cookies and local storage to a file so subsequent tests start already logged in without repeating the UI login$qz$, true), ($qz$It recorded the login steps so Playwright can replay the clicks before each test$qz$, false), ($qz$It stored the user’s password in plain text so tests can re-enter it automatically$qz$, false), ($qz$It enabled session sharing so all parallel workers mutate one live server session together$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Why do many teams prefer a programmatic or API-based login for their setup step over driving the login form in the browser?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$It is faster and far less flaky, since it avoids the UI entirely and does not break when the login page markup changes$qz$, true), ($qz$API login is the only method that can produce a valid storageState file; UI login cannot$qz$, false), ($qz$Browser login cannot set cookies, so an API call is technically required to authenticate$qz$, false), ($qz$API login runs the real user journey more faithfully than clicking through the form$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You need tests for an admin and a standard user to run in the same suite. Which configuration approach keeps their sessions cleanly separated?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Define per-role Playwright projects, each with its own storageState file, and route each spec to the project whose role it needs$qz$, true), ($qz$Log in as admin once and downgrade the role inside each standard-user test at run time$qz$, false), ($qz$Store both roles in a single storageState file and hope the correct one is used per test$qz$, false), ($qz$Share one session and switch roles by editing cookies mid-test from within each spec$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A test passes in isolation but fails when the whole file runs, and the failure changes depending on which test ran before it. What is the most likely cause?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$Order dependence from shared mutable state: an earlier test leaves data or session state behind that a later test unknowingly relies on or is broken by$qz$, true), ($qz$A genuine product bug that only appears when the server is under the load of several tests$qz$, false), ($qz$Playwright caps the number of tests per file, so later tests are throttled and fail$qz$, false), ($qz$The assertions are correct but the reporter miscounts results when many tests run together$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What is the risk of every test creating a user named `test@example.com` with a fixed username?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Collisions: parallel or repeated runs clash on the unique field and fail non-deterministically or leave the database in a state that breaks later runs$qz$, true), ($qz$None; a fixed identity is the recommended way to make tests deterministic$qz$, false), ($qz$The only risk is slightly slower tests because the server must check the name each time$qz$, false), ($qz$Playwright rejects duplicate email strings within a run and skips the affected tests silently$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A team seeds test data by calling the product’s own API in a fixture before each test and deletes it afterwards. Compared with relying on a shared, pre-populated database, what is the main advantage?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Each test owns and controls its own data, so tests do not interfere with each other and can run in parallel without stepping on shared fixtures$qz$, true), ($qz$It removes the need to assert anything, since API-seeded data is guaranteed correct$qz$, false), ($qz$It makes the tests independent of the product entirely, so they still pass when the product is broken$qz$, false), ($qz$A shared database is always faster, so the only reason to seed per test is code style$qz$, false)) as v(t, c) returning question_id),
q7 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A saved `storageState` file that used to work now causes tests to start on the login page again. What is the most likely explanation?$qz$, 'multiple_choice', 7 from newq returning id),
