q8 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Which practice most directly makes it safe to run tests in a random order?$qz$, 'multiple_choice', 8 from newq returning id),
a8 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q8.id, v.t, v.c from q8, (values ($qz$Each test creates the state it needs and cleans up after itself, depending on no artefact left by another test$qz$, true), ($qz$Fixing the order in the config so it can never change, and documenting the required sequence$qz$, false), ($qz$Running everything in a single worker so nothing overlaps in time$qz$, false), ($qz$Adding a fixed wait at the start of each test to let previous state settle$qz$, false)) as v(t, c) returning question_id),
q9 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A colleague’s new test authenticates as admin but forgets to specify a project, so it inherits the default standard-user storageState and fails with a permissions error. What does this teach about test-data and state strategy?$qz$, 'multiple_choice', 9 from newq returning id),
a9 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q9.id, v.t, v.c from q9, (values ($qz$The role a test runs as should be explicit and enforced by configuration, not left to an inherited default that is easy to get silently wrong$qz$, true), ($qz$Admin tests are impossible in Playwright and should be run manually instead$qz$, false), ($qz$The permissions error is a product bug, since the credentials were valid admin credentials$qz$, false), ($qz$storageState cannot represent an admin role, so a fresh UI login was required$qz$, false)) as v(t, c) returning question_id),
q10 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What is the purpose of pairing `page.on('request')` or an API teardown step with data created during a test?$qz$, 'multiple_choice', 10 from newq returning id),
a10 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q10.id, v.t, v.c from q10, (values ($qz$To ensure created records are removed after the test so the environment does not accumulate leftover data that leaks into later runs$qz$, true), ($qz$To make the test assert faster by caching every network request it observed$qz$, false), ($qz$To force the test to fail if any network request occurs, proving the page is static$qz$, false), ($qz$To replay the same requests on the next run instead of hitting the real server$qz$, false)) as v(t, c) returning question_id),
q11 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A suite runs green locally but flakes in CI, and the flaky tests all read a "welcome back" banner that only appears on a user’s second-ever login. What is the underlying design flaw?$qz$, 'multiple_choice', 11 from newq returning id),
