q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What does `expect(res.ok()).toBeTruthy()` actually check, and why is it weaker than checking a specific status?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$It only checks the status is in the 200–299 range, so it would pass for a 204 when you expected a 201, hiding a real behavioural difference$qz$, true), ($qz$It checks the response body is valid JSON, which is stricter than a status check$qz$, false), ($qz$It verifies the response arrived within the timeout, unrelated to the status code$qz$, false), ($qz$It is identical to `toBe(200)` and there is no practical difference between them$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A hybrid test seeds data via the API and then verifies it in the UI. Which sequencing best avoids a race where the UI loads before the data exists?$qz$, 'multiple_choice', 6 from newq returning id),
